import json
import urllib.request
import urllib.parse
import time

papers = json.load(open('/tmp_workspace/oral_papers_with_authors.json'))

def search_s2(title, first_author=None):
    """Search Semantic Scholar for a paper and return author affiliations"""
    query = urllib.parse.quote(title[:100])
    url = f"https://api.semanticscholar.org/graph/v1/paper/search?query={query}&fields=title,authors.affiliations&limit=3"
    req = urllib.request.Request(url, headers={'User-Agent': 'Mozilla/5.0'})
    try:
        resp = urllib.request.urlopen(req, timeout=10)
        data = json.loads(resp.read())
        if data.get('data'):
            for paper in data['data']:
                if paper.get('title', '').lower().strip() == title.lower().strip() or title.lower().split(':')[0] in paper.get('title', '').lower():
                    return paper.get('authors', [])
            # If no exact match, return the first result
            return data['data'][0].get('authors', [])
    except Exception as e:
        print(f"  Error: {e}")
    return None

# Test with one paper
test_paper = papers[0]
print(f"Testing: {test_paper['title']}")
authors = search_s2(test_paper['title'])
if authors:
    for a in authors[:3]:
        print(f"  {a.get('name')}: {a.get('affiliations')}")
time.sleep(2)

# Test with another paper
test_paper = papers[10]
print(f"\nTesting: {test_paper['title']}")
authors = search_s2(test_paper['title'])
if authors:
    for a in authors[:3]:
        print(f"  {a.get('name')}: {a.get('affiliations')}")
